(self.webpackChunksite=self.webpackChunksite||[]).push([[6620],{7037:e=>{"use strict";e.exports=JSON.parse('{"slug":"number-slide","title":"Number Slide","authors":[{"name":"Giovana Ferreira Waterkemper","contact":"gi-water-143844","contactType":"github","contactUrl":"https://github.com/gi-water-143844"},{"name":"Jamily Goncalves de Sales Souza","contact":"JamilyGSS","contactType":"github","contactUrl":"https://github.com/JamilyGSS"}],"date":1783123200000,"readme":"<p>Number Slide is a classic 15-puzzle game developed with WASM-4.</p>\\n<p>The objective is to arrange the numbered tiles in ascending order by sliding them into the empty space.</p>\\n<h2>Controls</h2>\\n<ul>\\n<li>Arrow Keys: Move the tiles</li>\\n<li>X: Start the game</li>\\n</ul>\\n<p>Good luck and have fun!</p>"}')}}]);